import{_ as i,a as o,b as a,c as s,d as n,e as l,f as d,g as c,h as p,i as u,j as m,k as h,l as v}from"./chunks/Install17a.WxJn2Ju7.js";import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r}from"./chunks/DIS.DdpTdGGD.js";import{_ as f}from"./chunks/EN.P9aPnFBv.js";import{_ as b}from"./chunks/Install17.CwCXrGHM.js";import{_ as g,o as y,c as _,a3 as A}from"./chunks/framework.g9mfNVRQ.js";const P=JSON.parse('{"title":"Installation","description":"","frontmatter":{"source_hash":"4b874be737","source_commit":"0bbdbd2"},"headers":[],"relativePath":"fr/install/install.md","filePath":"fr/install/install.md"}'),z={name:"fr/install/install.md"};function x(E,e,S,T,I,D){return y(),_("div",null,[...e[0]||(e[0]=[A('<p>Une fois le téléchargement terminé, installez l&#39;apk de xDrip.</p><img src="'+i+'" style="zoom:50%;"><p>Sur les versions récentes d&#39;Android, vous verrez un avertissement de Google Play Protect indiquant que l&#39;application n&#39;est pas sûre et a été conçue pour d&#39;anciennes versions d&#39;Android. Ignorez-le avec Plus de détails, puis Installer quand même.</p><img src="'+o+'" style="zoom:50%;"><p><strong>Vous devez <a href="https://developer.android.com/distribute/marketing-tools/alternative-distribution#unknown-sources" target="_blank" rel="noreferrer">autoriser l&#39;installation d&#39;applications de sources inconnues</a> dans les paramètres de sécurité d&#39;Android.</strong><br> Les versions officielles de xDrip sont exemptes de virus et de logiciels malveillants : comme le code est open source et contrôlé par le développeur principal, sa distribution est sûre si vous le téléchargez depuis GitHub.</p><img src="'+a+'" style="zoom:50%;"><p>Appuyez sur <code>Paramètres</code> puis activez <code>Autoriser cette source</code>.</p><img src="'+s+'" style="zoom:50%;"><p>Une fois l&#39;installation terminée, ouvrez xDrip.</p><img src="'+n+'" style="zoom:75%;"><h3 id="understand-what-is-xdrip" tabindex="-1">Comprendre ce qu&#39;est xDrip <a class="header-anchor" href="#understand-what-is-xdrip" aria-label="Permalink to &quot;Comprendre ce qu&#39;est xDrip {#understand-what-is-xdrip}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title"><strong>Lisez</strong> l&#39;avertissement important</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+l+'" style="zoom:50%;"></p><img src="'+d+'" style="zoom:50%;"> Do NOT use or rely on this software or any associated materials for any medical purpose or decision. Do NOT rely on this system for any real-time alarms or time critical data. Do NOT use or rely on this system for treatment decisions or use as a substitute for professional healthcare judgement. All software and materials have been provided for informational purposes only as a proof of concept to assist possibilities for further research. No claims at all are made about fitness for any purpose and everything is provided **AS IS**. Any part of the system can fail at any time. Always seek the advice of a qualified healthcare professional for any medical questions. Always follow your glucose-sensor or other device manufacturers&#39; instructions when using any equipment; do not discontinue use of accompanying reader or receiver, other than as advised by your doctor. This software is not associated with or endorsed by any equipment manufacturer and all trademarks are those of their respective owners. Your use of this software is entirely at your own risk. No charge has been made by the developers for the use of this software. This is an open-source project which has been created by volunteers. The source code is published free and open-source for you to inspect and evaluate. By using this software and/or website you agree that you are over 18 years of age and have read, understood and agree to all of the above. </div><br><p><strong>Lisez</strong> le CLUF (EULA).</p><div class="warning custom-block"><p class="custom-block-title">Assurez-vous de bien le comprendre avant d&#39;enregistrer.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+c+'" style="zoom:50%;"></p><p>xDrip MUST NOT BE USED TO MAKE MEDICAL DECISIONS.<br> IT IS A RESEARCH TOOL ONLY AND IS PROVIDED &quot;AS IS&quot; WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE.<br> THE ENTIRE RISK AS TO THE QUALITY AND PERFORMANCE OF THE PROGRAM IS WITH YOU.<br> SHOULD THE PROGRAM PROVE DEFECTIVE, YOU ASSUME THE COST OF ALL NECESSARY SERVICING, REPAIR OR CORRECTION.</p></div><br><h3 id="authorize-background-activity" tabindex="-1">Autoriser l&#39;activité en arrière-plan <a class="header-anchor" href="#authorize-background-activity" aria-label="Permalink to &quot;Autoriser l&#39;activité en arrière-plan {#authorize-background-activity}&quot;">​</a></h3><p>xDrip doit avoir le droit de fonctionner en arrière-plan : il doit être exclu de l&#39;optimisation de la batterie (liste blanche). C&#39;est indispensable à son bon fonctionnement. Il devrait vous demander cette autorisation. S&#39;il ne le fait pas, ou si vous devez le vérifier plus tard, vous devrez le contrôler dans <code>Paramètres</code> - <code>Applications</code> - <code>xDrip</code> de votre téléphone. Consultez le manuel de votre téléphone, car cela dépend de la version d&#39;Android et du fabricant.</p><div class="admonition xdripitem"><p class="admonition-title">Veuillez autoriser les permissions</p><p> xDrip+ a besoin d&#39;être sur liste blanche pour des performances correctes</p><p>      <span style="background-color:white;color:black;"> D&#39;accord </span></p></div><img src="'+p+'" style="zoom:75%;"><p><em>Remarque : à partir d&#39;Android 12, vous ne verrez plus la mention <strong>liste blanche</strong> (whitelisting).</em></p><p>Plus d&#39;informations <a href="./../troubleshoot/savings.html#apps-battery-savings">ici</a>.</p><br><h3 id="authorize-notifications" tabindex="-1">Autoriser les notifications <a class="header-anchor" href="#authorize-notifications" aria-label="Permalink to &quot;Autoriser les notifications {#authorize-notifications}&quot;">​</a></h3><p>xDrip doit avoir accès aux notifications du téléphone pour fonctionner comme prévu.</p><img src="'+u+'" style="zoom:75%;"><br><h2 id="verify-which-version-is-installed" tabindex="-1">Vérifier la version installée <a class="header-anchor" href="#verify-which-version-is-installed" aria-label="Permalink to &quot;Vérifier la version installée {#verify-which-version-is-installed}&quot;">​</a></h2><p>Appuyez sur le bouton retour de votre téléphone jusqu&#39;à revenir à l&#39;écran principal. Sélectionnez le menu hamburger en haut à gauche, puis <code>État du système</code>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p>  État du système</p></div><p>La version actuelle s&#39;affiche après <code>Version</code>. Dans l&#39;exemple ci-dessous, le 28 janvier 2022.</p><img src="'+m+'" style="zoom:75%;"><p>Sur les versions les plus récentes, vous la trouverez sur toutes les pages de l&#39;état du système.</p><img src="'+h+'" style="zoom:76%;"><p>Consultez <a href="./../use/update.html">cette page</a> pour mettre à jour ou revenir à une version antérieure.</p><br><h2 id="make-sure-xdrip-will-not-be-put-to-sleep" tabindex="-1">Empêcher la mise en veille de xDrip <a class="header-anchor" href="#make-sure-xdrip-will-not-be-put-to-sleep" aria-label="Permalink to &quot;Empêcher la mise en veille de xDrip {#make-sure-xdrip-will-not-be-put-to-sleep}&quot;">​</a></h2><p>Ces réglages sont ceux par défaut, mais vérifiez quand même qu&#39;ils sont exactement comme ci-dessous. À chaque mise à jour de votre téléphone, revenez les vérifier : désactivez puis réactivez les cases qui doivent être cochées pour forcer les réglages.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres moins courants<br>   Autres options diverses<br>    Exécutez Collector au premier plan</p></div><p>Depuis le retrait de la prise en charge d&#39;Android 7 (<a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 juillet 2026</a>), le collecteur fonctionne toujours au premier plan sur Android 8.0 et plus récent : il n&#39;y a plus d&#39;interrupteur pour cela. Le graphique de la notification persistante, dans le volet déroulant de votre téléphone, est indispensable pour maintenir l&#39;application active et s&#39;affiche toujours.</p><div class="admonition xdripitem"><p class="admonition-title">Notification persistante compacte <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p><p> Activer pour masquer le graphique dans la notification et afficher uniquement la valeur de glucose actuelle.</p></div><p>Si vous préférez ne pas afficher le graphique dans la notification persistante, activez <code>Notification persistante compacte</code> pour n&#39;afficher que la valeur de glucose actuelle.</p><div class="admonition xdripitem"><p class="admonition-title">Invité pour l’optimisation de la batterie <span class="symbol"><img src="'+r+'" style="zoom:75%;"></span></p><p> Sur Android 6+ s&#39;assurer que l&#39;optimisation de la batterie est désactivée (recommandé).</p></div><p><code>Invité pour l’optimisation de la batterie</code> doit être <strong>désactivé</strong>, car vous devriez avoir accepté la <a href="#authorize-background-activity">liste blanche de la batterie</a> pendant l&#39;installation. Sinon, excluez xDrip de l&#39;optimisation de la batterie dans les paramètres Android.</p><div class="admonition xdripitem"><p class="admonition-title">Solutions de contournement Wake <span class="symbol"><img src="'+f+'" style="zoom:75%;"></span></p><p> Utiliser des contournements pour éviter le comportement Android non standard de certains terminaux. Sans cela, les collecteurs ne peuvent pas obtenir les données.</p></div><p>Anciennement « Samsung workaround », cette option corrige le non-respect des spécifications Android par certains fabricants. Elle devrait s&#39;activer automatiquement sur certains smartphones. Recommandé.</p><h3 id="enable-location" tabindex="-1">Activer la localisation <a class="header-anchor" href="#enable-location" aria-label="Permalink to &quot;Activer la localisation {#enable-location}&quot;">​</a></h3><p>Sur les versions récentes d&#39;Android (6 et plus), la localisation est <a href="https://developer.android.com/training/location/permissions" target="_blank" rel="noreferrer">obligatoire</a> pour permettre la connexion Bluetooth Low Energy.<br> Si vous utilisez xDrip avec un capteur ou un transmetteur Bluetooth, vous <strong>devez</strong> activer la localisation (Paramètres Android -&gt; <a href="https://support.google.com/android/answer/3467281" target="_blank" rel="noreferrer">Localisation</a>) et autoriser xDrip à y accéder. Consultez le manuel de votre téléphone, car cela dépend de la version d&#39;Android et du fabricant.</p><p>Veillez à sélectionner Toujours autoriser dans les paramètres.</p><img src="'+v+'" style="zoom:75%;"><img src="'+b+'" style="zoom:75%;"><br><p>Passez à la <a href="./datasource.html">sélection de la source de données</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Dernière modification le 18/7/2026</em></a></p>',57)])])}const C=g(z,[["render",x]]);export{P as __pageData,C as default};
